    protected function prepareForValidation(): void
    {
        $repeaters = [];
        foreach (['why_items', 'statistics', 'trust_items', 'industry_items', 'process_items', 'technology_items', 'faq_items', 'core_values', 'work_items'] as $key) {
            $items = collect($this->input($key, []))
                ->filter(fn (array $item): bool => filled($item['title'] ?? null))
                ->values()
                ->all();
            if ($items !== []) {
                $repeaters[$key] = $items;
            }
        }

        $this->merge([
            'is_indexable' => $this->boolean('is_indexable'),
            'auto_reply_enabled' => $this->boolean('auto_reply_enabled'),
            'business_hours' => collect($this->input('business_hours', []))->map(fn (array $hours): array => array_merge($hours, ['is_closed' => filter_var($hours['is_closed'] ?? false, FILTER_VALIDATE_BOOLEAN)]))->values()->all(),
            'ecosystem_enabled' => $this->boolean('ecosystem_enabled'),
            'industries_enabled' => $this->boolean('industries_enabled'),
            'process_enabled' => $this->boolean('process_enabled'),
            'technology_enabled' => $this->boolean('technology_enabled'),
            'faq_enabled' => $this->boolean('faq_enabled'),
            'steps' => collect($this->input('steps', []))->filter(fn ($item): bool => filled($item))->values()->all(),
            'bullets' => collect($this->input('bullets', []))->filter(fn ($item): bool => filled($item))->values()->all(),
